void pdf_flag_object(struct pdf_struct *pdf, struct pdf_obj *obj, enum pdf_flag flag) {
    if (!pdf || !obj) {
        return;
    }

    // Set the corresponding flag bit in the PDF object
    obj->flags |= (1 << flag);

    // Early exit if debug flag is not enabled
    if (!(pdf->flags & PDF_FLAG_DEBUG)) {
        return;
    }

    // Determine the debug message based on the flag
    const char *message = nullptr;
    switch (flag) {
        case PDF_FLAG_UNCLOSED_DICT:
            message = "Unclosed dictionary";
            break;
        case PDF_FLAG_BAD_STREAM_FILTER:
            message = "Bad stream filter";
            break;
        case PDF_FLAG_ENCRYPTED:
            message = "Object is encrypted";
            break;
        // Add more cases as needed for other flag values
        default:
            message = "Unknown flag";
            break;
    }

    // Log the debug message with object ID
    if (message) {
        std::cerr << message << " in object ID " << obj->id << std::endl;
    }
}

void pdf_set_flag(struct pdf_struct *pdf, struct pdf_obj *obj, enum pdf_flag flag) {
    if (!pdf || !obj) {
        return;
    }

    pdf->flags |= (1 << flag);

    if (!pdf->debug_enabled) {
        return;
    }

    const char *message = nullptr;

    switch (flag) {
        case PDF_FLAG_UNCLOSED_DICT:
            message = "Unclosed dictionary in object";
            break;
        case PDF_FLAG_BAD_STREAM_FILTER:
            message = "Invalid stream filter in object";
            break;
        case PDF_FLAG_ENCRYPTED:
            message = "Object is encrypted";
            break;
        default:
            message = "Unknown flag set";
            break;
    }

    printf("%s (object ID: %d)\n", message, obj->id);
}

